const on = msg.req.params.state === 'on';
flow.set('jitterEnabled', on);
msg.headers = { 'content-type': 'text/html' };
msg.payload = `<html><body style="font-family:sans-serif;text-align:center;padding-top:40px"><h2>Demo jitter is now <b>${on ? 'ON' : 'OFF'}</b></h2><p>You can close this tab.</p></body></html>`;
return msg;

 // --- Validate incoming MQTT payload ---
let payload = msg.payload;

if (
    !payload ||
    !payload.device ||
    !payload.device.name ||
    !payload.device.metrics ||
    typeof payload.device.metrics !== "object" ||
    Array.isArray(payload.device.metrics)
) {
    node.warn("Invalid payload: " + JSON.stringify(payload));
    return null;
}

let deviceName = payload.device.name;

// --- Normalize metric keys ---
// Example: "temp(C)" -> "temp"
// "gas resistance" -> "gas"
let m = {};

for (let key in payload.device.metrics) {
    let cleanedKey = key.replace(/\s*\(.*?\)\s*/g, "").trim();

    if (cleanedKey.toLowerCase() === "gas resistance") {
        cleanedKey = "gas";
    }

    if (cleanedKey === "SOUND") {
        cleanedKey = "sound_level";
    }

    m[cleanedKey] = payload.device.metrics[key];
}

// --- Demo jitter ---
// Adds +/-3% variation when enabled.
if (flow.get("jitterEnabled")) {
    const jitterPct = 0.03;

    for (let key of [
        "temp", "pressure", "humidity", "gas",
        "proximity", "X", "Y", "Z",
        "ambient_light", "AQI", "sound_level"
    ]) {
        if (typeof m[key] === "number") {
            m[key] *= 1 + (Math.random() * 2 - 1) * jitterPct;
        }
    }
}

// --- Humidity score ---
// Maximum score: 25
// Ideal humidity range: 38% to 42%
// Score decreases toward zero at 0% and 100%.

function humScore(h) {
    const maxScore = 25;

    if (!Number.isFinite(h)) return 0;

    h = Math.max(0, Math.min(100, h));

    if (h < 38) {
        return maxScore * (h / 38);
    }

    if (h <= 42) {
        return maxScore;
    }

    return maxScore * ((100 - h) / 58);
}

// --- Gas score ---
// Existing formula retained for compatibility.

function gasScore(g) {
    const w = 0.75;
    const lo = 10000;
    const hi = 300000;

    if (!Number.isFinite(g)) return 0;

    return Math.max(
        0,
        Math.min(
            75,
            (w / (hi - lo)) * g -
            (lo * (w / (hi - lo))) * 100
        )
    );
}

// --- Calculate air quality scores ---
let humidity = Number(m.humidity ?? 0);
let gas = Number(m.gas ?? 0);

let hs = humScore(humidity);

// FIX: Pass the defined gas variable.
let gs = gasScore(gas);

let aqs = hs + gs;

// Calculated IAQ score (not used for the
// InfluxDB IAQScore field).
let calculatedIAQ = (100 - aqs) * 5;

// --- XYZ accelerometer calculations ---
let sf = 2 / 1024;

let X = (m.X || 0) * sf;
let Y = (m.Y || 0) * sf;
let Z = (m.Z || 0) * sf;

let mag = Math.sqrt(X * X + Y * Y + Z * Z) || 0.0001;

let tilt = Math.acos(
    Math.min(1, Math.abs(Z / mag))
) * 180 / Math.PI;

if (tilt > 90) {
    tilt = 180 - tilt;
}

let pitch = Math.atan2(
    Y,
    Math.sqrt(X * X + Z * Z)
) * 180 / Math.PI;

let roll = Math.atan2(
    X,
    Math.sqrt(Y * Y + Z * Z)
) * 180 / Math.PI;

// --- Build InfluxDB payload ---
// Device tag keeps all four sensors separate.

msg.payload = [
    {
        temperature: m.temp,
        pressure: m.pressure,
        humidity: m.humidity,
        gas: m.gas,
        proximity: m.proximity,

        X: m.X,
        Y: m.Y,
        Z: m.Z,

        ambient_light: m.ambient_light,

        humidity_score: parseFloat(hs.toFixed(2)),
        gas_score: parseFloat(gs.toFixed(2)),
        air_quality_score: parseFloat(aqs.toFixed(2)),

        // Keep sensor-reported AQI
        IAQScore: m.AQI,

        magnitude: parseFloat(mag.toFixed(4)),
        tilt: Math.round(tilt),
        pitch: Math.round(pitch),
        roll: Math.round(roll),

        sound_level: m.sound_level
    },
    {
        device: deviceName
    }
];

return msg;
